<script setup lang="ts">import{computed}from'vue';import{useRoute,useRouter}from'vue-router';const route=useRoute(),router=useRouter();const reason=computed(()=>String(route.query.reason||'not-found'));const copy=computed(()=>reason.value==='feature'?['当前企业尚未开通该功能','可以在“系统设置 → 功能模块”查看套餐权益与试用状态。']:reason.value==='forbidden'?['当前账号没有访问权限','请联系企业主管调整角色或功能权限。']:reason.value==='choose-enterprise'?['请先进入具体企业','平台管理员可从企业管理页面选择企业后查看相关数据。']:['没有找到这个页面','请返回工作台继续操作。']);</script>
<template><section class="panel state-panel"><div class="state-icon">!</div><h2>{{copy[0]}}</h2><p>{{copy[1]}}</p><button class="primary" @click="router.back()">返回上一页</button></section></template>
